//! Embedded 1-bit monospaced bitmap font for the level editor's UI text.
//!
//! Generated once from the system Menlo face (see the generator in the
//! `level-editor text` work); vendored here so the editor needs no font asset
//! or text-rendering dependency. Each glyph is `GLYPH_H` rows of a `GLYPH_W`-bit
//! bitmap (MSB = leftmost pixel), covering printable ASCII 0x20..=0x7E. Drawn
//! with `fill_rect`, matching how the editor draws its other glyphs.

use sdl2::pixels::Color;
use sdl2::rect::Rect;
use sdl2::render::WindowCanvas;

pub const GLYPH_W: i32 = 7;
pub const GLYPH_H: i32 = 13;
/// Pixels between adjacent glyphs, in unscaled font pixels.
pub const GLYPH_GAP: i32 = 1;

const FIRST_CHAR: u8 = 0x20;
const LAST_CHAR: u8 = 0x7E;

