/// Width in pixels a string occupies at the given integer `scale`.
pub fn text_width(s: &str, scale: i32) -> i32 {
    let n = s.chars().count() as i32;
    if n == 0 {
        return 0;
    }
    (n * GLYPH_W + (n - 1) * GLYPH_GAP) * scale
}

/// Total line height in pixels at the given integer `scale`.
pub fn line_height(scale: i32) -> i32 {
    GLYPH_H * scale
}

/// Draw `text` with its top-left corner at (`x`, `y`) in `color`, each font
/// pixel blown up to a `scale`x`scale` block. Unknown characters render as a
/// blank cell. Returns the x just past the drawn text.
pub fn draw_text(canvas: &mut WindowCanvas, x: i32, y: i32, text: &str, color: Color, scale: i32) -> i32 {
    canvas.set_draw_color(color);
    let mut cx = x;
    for ch in text.chars() {
        let code = ch as u32;
        if (FIRST_CHAR as u32..=LAST_CHAR as u32).contains(&code) {
            let glyph = &GLYPHS[(code as u8 - FIRST_CHAR) as usize];
            for (row, bits) in glyph.iter().enumerate() {
                for col in 0..GLYPH_W {
                    if bits & (1 << (GLYPH_W - 1 - col)) != 0 {
                        let _ = canvas.fill_rect(Rect::new(
                            cx + col * scale,
                            y + row as i32 * scale,
                            scale as u32,
                            scale as u32,
                        ));
                    }
                }
            }
        }
        cx += (GLYPH_W + GLYPH_GAP) * scale;
    }
    cx
}
